<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<mappingRoot xmlns="http://www.ibm.com/2008/ccl/Mapping" xmlns:map="default" domainID="com.ibm.msl.mapping.xml" domainIDExtension="mb" mainMap="true" targetNamespace="default" version="8.0.5.0">
    <inlinedXMLSchema>
        <![CDATA[<?xml version="1.0" encoding="UTF-8" standalone="no"?> 
<xsd:schema xmlns:xsd="http://www.w3.org/2001/XMLSchema"> 
    
     
      
       
           
      
         
       
    
        
     
      
   
  <xsd:element name="OUT" nillable="true" type="xsd:string"/> 
    
        
   
  <xsd:element name="B" nillable="true" type="xsd:long"/> 
    
        
   
  <xsd:element name="A" nillable="true" type="xsd:long"/> 
    
    
 
</xsd:schema> 
]]>
    </inlinedXMLSchema>
    <input inlinedXMLSchema="true" path="../schema_0.xsd" var="var5"/>
    <input path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/JsonDomainMsg.xsd" var="var1"/>
    <output path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/JsonDomainMsg.xsd" var="var3"/>
    <imports>
        <import kind="esql" namespace="/Esql_file_mod.esql"/>
    </imports>
    <namespaces>
        <namespace kind="supplement" prefix="out" uri="http://www.ibm.com/iib/msl/json"/>
        <namespace kind="extension" prefix="xs" uri="http://www.w3.org/2001/XMLSchema"/>
        <namespace kind="extension" prefix="Esql_file_mod" uri="/Esql_file_mod.esql"/>
    </namespaces>
    <generation engine="xquery"/>
    <mappingDeclaration name="mf1_Mapping">
        <input namespace="http://www.ibm.com/iib/msl/json" path="$var1/mb:msg(JSON,assembly,JSON,Properties)" var="MessageAssembly">
            <cast castType="userDefined" path="$MessageAssembly/JSON/Data/type('anyType')" qualifier="{http://www.ibm.com/iib/msl/json}JSONObject" ref="var1"/>
            <cast castType="userDefined" path="$MessageAssembly/JSON/spath('Data',2)/any" qualifier="A" ref="var5"/>
            <cast castType="userDefined" path="$MessageAssembly/JSON/spath('Data',2)/any" qualifier="B" ref="var5"/>
        </input>
        <output namespace="http://www.ibm.com/iib/msl/json" path="$var3/mb:msg(JSON,assembly,JSON,Properties)" var="MessageAssembly2">
            <cast castType="userDefined" path="$MessageAssembly2/JSON/Data/type('anyType')" qualifier="{http://www.ibm.com/iib/msl/json}JSONObject" ref="var3"/>
            <cast castType="userDefined" path="$MessageAssembly2/JSON/spath('Data',2)/any" qualifier="OUT" ref="var5"/>
        </output>
        <move>
            <input path="$MessageAssembly/Properties"/>
            <output path="$MessageAssembly2/Properties"/>
        </move>
        <condition>
            <if>
                <input path="$MessageAssembly/JSON/spath('Data',2)/A" var="A"/>
                <output path="$MessageAssembly2/JSON/spath('Data',2)/OUT"/>
                <test lang="xpath">$A&lt;0</test>
                <move>
                    <input path="$A/."/>
                    <output path="."/>
                </move>
            </if>
            <elseif>
                <input path="$MessageAssembly/JSON/spath('Data',2)/A" var="A2"/>
                <input path="$MessageAssembly/JSON/spath('Data',2)/B" var="B"/>
                <output path="$MessageAssembly2/JSON/spath('Data',2)/OUT"/>
                <test lang="xpath">$B&gt;0 and $A&gt;0</test>
                <customFunction lang="esql" ref="Esql_file_mod:ADD">
                    <input path="$A2/." var="A3"/>
                    <input path="$B/." var="B1"/>
                    <output path="."/>
                    <param name="parm1" value="$A3"/>
                    <param name="B" value="$B1"/>
                </customFunction>
            </elseif>
            <else>
                <input path="$MessageAssembly/JSON/spath('Data',2)/B"/>
                <output path="$MessageAssembly2/JSON/spath('Data',2)/OUT"/>
                <move>
                    <input path="."/>
                    <output path="."/>
                </move>
            </else>
        </condition>
    </mappingDeclaration>
</mappingRoot>
